import*as THREE from'three';import{skinAttributes,createSkin,DEFAULT_SKIN}from'../baseline/kaopu-skin-workbench/src/SkinMaterial.js';
const json=async p=>{const r=await fetch(p);if(!r.ok)throw Error('HTTP '+r.status);return r.json();},bytes=async p=>{const r=await fetch(p);if(!r.ok)throw Error('HTTP '+r.status);return r.arrayBuffer();};
const[meta,c,states]=await Promise.all([json('../research/neutral.json'),json('../baseline/kaopu-skin-workbench/assets/canonical.json'),json('../research/ablation-states.json')]);
const canvas=document.querySelector('canvas'),renderer=new THREE.WebGLRenderer({canvas,antialias:true,powerPreference:'low-power'});renderer.setSize(960,960,false);renderer.setPixelRatio(1);renderer.setClearColor(0x242c32);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.05;
const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(31,1,.01,10);scene.add(new THREE.HemisphereLight(0xffffff,0x353535,.7));const key=new THREE.DirectionalLight(0xffffff,3);key.position.set(-2,3,4);scene.add(key);const rim=new THREE.DirectionalLight(0xffffff,1.3);rim.position.set(2,2,-2);scene.add(rim);
const display=v=>{const out=new Float32Array(v.length);for(let i=0;i<v.length;i+=3)out.set([v[i],v[i+2],-v[i+1]],i);return out;},geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.BufferAttribute(display(meta.vertices),3));geometry.setIndex(new THREE.BufferAttribute(new Uint32Array(meta.faces),1));geometry.computeVertexNormals();const model={vertexCount:meta.vertices.length/3,bodyCount:meta.bodyCount,faces:new Uint32Array(meta.faces),gnm:{template:meta.headTemplate,regionId:meta.headRegions,componentId:meta.headComponents,materialId:meta.headMaterials},canonical:c};skinAttributes(model,geometry);
const skin=DEFAULT_SKIN(),runtime=createSkin(skin),normalMaterial=new THREE.MeshNormalMaterial(),mesh=new THREE.Mesh(geometry,runtime.material);scene.add(mesh);const cache=new Map();
async function vertices(name){if(!cache.has(name))cache.set(name,new Float32Array(await bytes('../research/'+name+'.bin')));return cache.get(name);}
window.neckDiagnostic={async show({age='young',stage='final',material='skin',view='rear3q',rake=false}){const v=await vertices(age+'-'+stage),base=await vertices(age+'-final');geometry.attributes.position.array.set(display(v));geometry.attributes.position.needsUpdate=true;geometry.computeVertexNormals();geometry.computeBoundingSphere();const st=states.find(x=>x.name===age+'-final').state;skin.enabled=material!=='gray';runtime.update();mesh.material=material==='normal'?normalMaterial:runtime.material;
 // Both variants use the published neutral skin-reference field, isolating
 // shape/normals from procedural-coordinate changes in this diagnostic.
 const ring=c.bodyRing.map(i=>[base[i*3],base[i*3+1],base[i*3+2]]),center=ring.reduce((a,b)=>a.map((x,i)=>x+b[i]/ring.length),[0,0,0]),target=new THREE.Vector3(center[0],center[2]+.064,-center[1]);const directions={rear:[0,0,-1],rear3q:[.72,0,-.70],rearLeft:[-.72,0,-.70],side:[1,0,0],front3q:[.64,0,.77]};camera.position.copy(target).add(new THREE.Vector3(...directions[view]).multiplyScalar(.64));camera.lookAt(target);camera.updateProjectionMatrix();key.position.set(rake?-3:-2,3,rake?.2:4);document.querySelector('#caption').textContent=`${age} • native age ${st.phenotypes.age}\n${stage} • ${material} • ${view}${rake?' • raking light':''}\nSame topology / camera / original skin reference`;renderer.render(scene,camera);const gl=renderer.getContext();return{age,ageValue:st.phenotypes.age,stage,material,view,vertexCount:v.length/3,triangles:meta.faces.length/3,glError:gl.getError()};},dispose(){geometry.dispose();runtime.material.dispose();normalMaterial.dispose();renderer.dispose();}};
await window.neckDiagnostic.show({});window.__ready=true;
